package com.vitna;
import com.vitna.Domain.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.math.BigDecimal;
import java.time.LocalDate;

@Transactional @RestController @RequestMapping("/api")
public class Api {
 final Accounts accounts; final Products products; final Lots lots; final Orders orders; final Lines lines; final Productions productions; final PasswordEncoder encoder;
 public Api(Accounts a,Products p,Lots l,Orders o,Lines li,Productions pr,PasswordEncoder e){accounts=a;products=p;lots=l;orders=o;lines=li;productions=pr;encoder=e;}
 Account user(Authentication auth){Account account=accounts.findByEmail(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));if(!account.active)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Cuenta desactivada");return account;}
 void allow(Authentication auth,Role... roles){if(!Arrays.asList(roles).contains(user(auth).role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 Map<String,Object> profile(Account a){return Map.of("id",a.id,"name",a.name,"email",a.email,"role",a.role,"active",a.active);}
 @GetMapping("/csrf") CsrfToken csrf(CsrfToken token){return token;}
 @GetMapping("/me") Object me(Authentication a){return accountDetails(user(a));}
 @GetMapping("/public/products") Object catalog(){return products.findByPublishedTrue().stream().map(p->Map.of("id",p.id,"name",p.name,"category",p.category,"description",p.description,"presentation",p.presentation)).toList();}
 @GetMapping("/public/contact") Object contact(){return Map.of("whatsapp",System.getenv().getOrDefault("VITNA_WHATSAPP",""));}
 @GetMapping("/products") Object products(Authentication a){var visible=user(a).role==Role.CLIENTE?products.findByPublishedTrue():products.findAll();Map<Long,BigDecimal> stock=new HashMap<>();for(Lot l:lots.findAll())if(l.status.equals("APROBADO")&&!l.expiry.isBefore(LocalDate.now()))stock.merge(l.product.id,l.quantity.subtract(l.reserved).max(BigDecimal.ZERO),BigDecimal::add);for(Product p:visible)p.availableStock=stock.getOrDefault(p.id,BigDecimal.ZERO);return visible;}
 @PostMapping("/products/barcode") Object generateBarcode(Authentication a){allow(a,Role.ADMIN);return Map.of("barcode",Product.newBarcode());}
 @PostMapping("/products") Product saveProduct(@RequestBody @Valid ProductRequest r,Authentication a){
  allow(a,Role.ADMIN);Product p=r.id()==null?new Product():products.findById(r.id()).orElseThrow();
  String sku=r.sku().trim().toUpperCase(Locale.ROOT);
  String barcode=r.barcode()==null||r.barcode().isBlank()?(p.barcode==null?Product.newBarcode():p.barcode):r.barcode().trim();
  if(!barcode.matches("[\\x21-\\x7E]{4,48}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El código de barras debe tener entre 4 y 48 caracteres, sin espacios ni tildes");
  products.findBySku(sku).filter(other->!Objects.equals(other.id,p.id)).ifPresent(other->{throw new ResponseStatusException(HttpStatus.CONFLICT,"El SKU ya pertenece a otro producto");});
  products.findByBarcode(barcode).filter(other->!Objects.equals(other.id,p.id)).ifPresent(other->{throw new ResponseStatusException(HttpStatus.CONFLICT,"El código de barras ya pertenece a otro producto");});
  p.sku=sku;p.barcode=barcode;p.name=r.name().trim();p.description=r.description().trim();p.category=r.category().trim();p.presentation=r.presentation().trim();p.price=r.price();p.published=r.published();return products.save(p);
 }
 record ProductRequest(Long id,@NotBlank @Size(max=60) String sku,@NotBlank @Size(max=150) String name,@NotBlank @Size(max=100) String category,@NotBlank @Size(max=150) String presentation,@NotBlank @Size(max=2000) String description,@NotNull @PositiveOrZero @Digits(integer=10,fraction=2) BigDecimal price,boolean published,@Size(max=48) String barcode){}
 @GetMapping("/users") Object users(Authentication a){allow(a,Role.ADMIN);return accounts.findAll().stream().map(this::profile).toList();}
 @PostMapping("/users") Object createUser(@RequestBody @Valid UserRequest r,Authentication a){allow(a,Role.ADMIN);String email=r.email().trim().toLowerCase(Locale.ROOT);if(accounts.findByEmailIgnoreCase(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Correo registrado");Account u=new Account();u.name=r.name().trim();u.email=email;u.phone=r.phone();u.document=r.document();u.address=r.address();u.role=r.role();u.passwordHash=encoder.encode(r.password());return profile(accounts.save(u));}
 record UserRequest(@NotBlank String name,@Email @NotBlank String email,@Size(min=10) @NotNull String password,@NotNull Role role,String phone,String document,String address){}
 Map<String,Object> accountDetails(Account account){Map<String,Object> details=new HashMap<>(profile(account));details.put("phone",account.phone);details.put("document",account.document);details.put("address",account.address);return details;}
 Account account(Long id){return accounts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Cuenta no encontrada"));}
 @GetMapping("/users/{id}") Object userDetails(@PathVariable Long id,Authentication auth){allow(auth,Role.ADMIN);return accountDetails(account(id));}
 record UserUpdate(@NotBlank @Size(max=150) String name,@NotBlank @Email @Size(max=254) String email,@NotNull Role role,@Size(max=30) String phone,@Size(max=30) String document,@Size(max=300) String address){}
 @PutMapping("/users/{id}") Object updateUser(@PathVariable Long id,@RequestBody @Valid UserUpdate request,Authentication auth){
  allow(auth,Role.ADMIN);Account actor=user(auth);Account target=account(id);String email=request.email().trim();
  if(actor.id.equals(id) && (!target.email.equals(email)||request.role()!=Role.ADMIN))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No puedes cambiar tu propio correo o rol desde administración");
  accounts.findByEmailIgnoreCase(email).filter(existing->!existing.id.equals(id)).ifPresent(existing->{throw new ResponseStatusException(HttpStatus.CONFLICT,"Correo registrado");});
  target.name=request.name().trim();target.email=email;target.role=request.role();target.phone=request.phone();target.document=request.document();target.address=request.address();return accountDetails(accounts.save(target));
 }
 record AccountStatus(@NotNull Boolean active){}
 @PatchMapping("/users/{id}/status") Object accountStatus(@PathVariable Long id,@RequestBody @Valid AccountStatus request,Authentication auth){allow(auth,Role.ADMIN);if(user(auth).id.equals(id)&&!request.active())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No puedes desactivar tu propia cuenta");Account target=account(id);target.active=request.active();return profile(accounts.save(target));}
 @GetMapping("/lots") Object lots(Authentication a){allow(a,Role.ADMIN,Role.ALMACENERO,Role.JEFE_PRODUCCION,Role.CALIDAD);return lots.findAll();}
 @GetMapping("/production/receipts") Object productionReceipts(Authentication a){allow(a,Role.ADMIN,Role.ALMACENERO);var received=lots.findAll().stream().map(l->l.productionId).filter(Objects::nonNull).collect(java.util.stream.Collectors.toSet());return productions.findAll().stream().filter(p->p.status.equals("TERMINADA")&&p.produced!=null&&p.produced.signum()>0&&!received.contains(p.id)).map(p->Map.of("id",p.id,"product",p.product,"quantity",p.produced)).toList();}
 @PostMapping("/lots") Lot receive(@RequestBody @Valid LotRequest r,Authentication a){allow(a,Role.ADMIN,Role.ALMACENERO);Lot l=new Lot();l.product=products.lockProduct(r.productId()).orElseThrow();l.quantity=r.quantity();if(r.productionId()!=null){Production p=productions.findById(r.productionId()).orElseThrow();if(!p.status.equals("TERMINADA")||p.produced==null||p.produced.signum()<=0)throw new ResponseStatusException(HttpStatus.CONFLICT,"La fabricación todavía no tiene una cantidad terminada");if(!p.product.id.equals(r.productId())||p.produced.compareTo(r.quantity())!=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El producto y la cantidad deben coincidir con la fabricación terminada");if(lots.findByProductionId(p.id).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Esta fabricación ya fue recibida en almacén");l.productionId=p.id;}String code=r.code().trim().toUpperCase(Locale.ROOT);if(lots.findByProductId(l.product.id).stream().anyMatch(existing->code.equalsIgnoreCase(existing.code)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Ya existe un lote con ese código para este producto");l.code=code;l.warehouse=r.warehouse().trim();l.expiry=r.expiry();return lots.save(l);}
 record LotRequest(@NotNull Long productId,@NotBlank @Size(max=100) String code,@NotBlank @Size(max=150) String warehouse,@NotNull @FutureOrPresent LocalDate expiry,@NotNull @Positive @Digits(integer=10,fraction=2) BigDecimal quantity,Long productionId){}
 @PostMapping("/lots/{id}/quality") Lot quality(@PathVariable Long id,@RequestBody Map<String,String> r,Authentication a){allow(a,Role.CALIDAD);String state=r.get("status");if(state==null||!List.of("APROBADO","CUARENTENA","RECHAZADO").contains(state))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Estado de calidad inválido");Lot l=lots.findById(id).orElseThrow();if(state.equals("APROBADO")&&l.expiry.isBefore(LocalDate.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"No se puede aprobar un lote vencido");if(!state.equals("APROBADO")&&l.reserved.signum()>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"El lote tiene reservas: cancela los pedidos afectados antes de cambiar su calidad");String note=Objects.toString(r.get("note"),"").trim();if(note.length()>1000||(!state.equals("APROBADO")&&note.isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Indica una observación de máximo 1000 caracteres para rechazar o poner en cuarentena");if(l.status.equals(state))throw new ResponseStatusException(HttpStatus.CONFLICT,"El lote ya tiene ese estado");l.qualityNote=note;l.reviewedBy=user(a).name;l.reviewedAt=java.time.Instant.now();l.status=state;return lots.save(l);}
 Map<String,Object> orderView(Order o){return Map.of("id",o.id,"status",o.status,"total",o.total,"address",o.address,"customer",profile(o.customer),"items",lines.findByOrderId(o.id).stream().map(l->Map.of("productId",l.product.id,"name",l.product.name,"sku",l.product.sku,"quantity",l.quantity,"unitPrice",l.unitPrice,"subtotal",l.unitPrice.multiply(l.quantity).setScale(2,java.math.RoundingMode.HALF_UP))).toList());}
 @GetMapping("/orders") Object orders(Authentication a){if(user(a).role==Role.CLIENTE)return orders.findByCustomerId(user(a).id).stream().map(this::orderView).toList();allow(a,Role.ADMIN,Role.ALMACENERO);boolean admin=user(a).role==Role.ADMIN;return orders.findAll().stream().filter(o->admin||List.of("CONFIRMADO","EN_PREPARACION","DESPACHADO","ENTREGADO").contains(o.status)).map(this::orderView).toList();}
 @PostMapping("/orders/{id}/cancel") Object cancelOwnOrder(@PathVariable Long id,Authentication auth){allow(auth,Role.CLIENTE);Order o=orders.findById(id).orElseThrow();if(!o.customer.id.equals(user(auth).id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Este pedido pertenece a otra cuenta");if(!o.status.equals("PENDIENTE_REVISION"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Solo puedes cancelar pedidos que todavía no han sido revisados");o.status="CANCELADO";orders.save(o);return orderView(o);}
 record Item(@NotNull Long productId,@NotNull @Positive @Digits(integer=10,fraction=2) BigDecimal quantity,@PositiveOrZero @Digits(integer=10,fraction=2) BigDecimal expectedPrice){Item(Long productId,BigDecimal quantity){this(productId,quantity,null);}}
 record Checkout(@NotBlank @Size(max=300) String address,@NotEmpty @Size(max=100) List<@Valid Item> items){}
 @PostMapping("/orders") @Transactional Object checkout(@RequestBody @Valid Checkout r,Authentication a){allow(a,Role.CLIENTE);Order o=new Order();o.customer=user(a);o.address=r.address().trim();orders.save(o);Map<Long,BigDecimal> quantities=new LinkedHashMap<>();for(Item item:r.items())quantities.merge(item.productId(),item.quantity(),BigDecimal::add);for(var entry:quantities.entrySet()){Item i=new Item(entry.getKey(),entry.getValue());Product p=products.findById(i.productId()).orElseThrow();if(!p.published)throw new ResponseStatusException(HttpStatus.CONFLICT,"Producto no publicado");if(r.items().stream().filter(item->item.productId().equals(p.id)).anyMatch(item->item.expectedPrice()!=null&&item.expectedPrice().compareTo(p.price)!=0))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cambió el precio de "+p.name+". Revisa el total actualizado antes de enviar otra vez.");BigDecimal available=lots.findByProductId(p.id).stream().filter(l->l.status.equals("APROBADO")&&!l.expiry.isBefore(LocalDate.now())).map(l->l.quantity.subtract(l.reserved)).reduce(BigDecimal.ZERO,BigDecimal::add);if(available.compareTo(i.quantity())<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Stock insuficiente: "+p.name);OrderLine line=new OrderLine();line.order=o;line.product=p;line.quantity=i.quantity();line.unitPrice=p.price;lines.save(line);o.total=o.total.add(p.price.multiply(i.quantity()).setScale(2,java.math.RoundingMode.HALF_UP));}return orderView(o);}
}


